    # ponytail: no max-subtraction, matches the PyTorch module exactly; inputs in [0,1) keep exp finite.
    y = jnp.exp(x)
    return y / jnp.sum(y, axis=CONFIG['axis'])

"""[bf16 variant] TopKMaxPooling: flatten spatial dims, take top-k per channel, mean of the top-k values."""
import jax
import jax.numpy as jnp
from jax import lax

CONFIG = {
    'name': 'TopKMaxPooling_8394__scale',
    'batch': 192,
    'channels': 256,
    'height': 64,
    'width': 64,
    'kmax': 1.0,
}


def _positive_k(k, n):
    # Mirrors TopKMaxPooling.get_positive_k (Python round, i.e. banker's rounding).
    if k <= 0:
        return 0
    if k < 1:
        return round(k * n)
    if k > n:
        return int(n)
    return int(k)


def create_inputs(dtype=jnp.bfloat16):
    key = jax.random.key(0)
    x = jax.random.uniform(
        key,
        (CONFIG['batch'], CONFIG['channels'], CONFIG['height'], CONFIG['width']),
        dtype=dtype,
    )
    return (x,)


def workload(x):
    b, c, h, w = x.shape
    n = h * w
    k = _positive_k(CONFIG['kmax'], n)
    top, _ = lax.top_k(x.reshape(b, c, n), k)
    return top.sum(axis=2) / k

"""[bf16 variant] Cast to float32 -> sqrt -> divide by 5.0 -> floor."""
import jax
import jax.numpy as jnp

CONFIG = {
    'name': 'TracedModule_1024__scale',
    'batch': 48,
    'channels': 16,
    'height': 512,
    'width': 512,
